with filtered_web_events as (select *, concat(page, ' ', event_type) as page_event_type from web_events where not (event_type = 'purchase' and event_type in ('search', 'click', 'page_view'))), summary as (select session_id, count(case when event_type = 'add_to_cart' then 1 end) as add_to_cart_count from filtered_web_events group by session_id) select * from summary order by add_to_cart_count desc, session_id limit 10;
